data.transform:
{
  "CONSTANTS": {
    "REQUEST": REQUEST,
    "INVENTORY": [
      REQUEST.inventory
    ],
    "WORKCENTER": REQUEST.workcenter,
    "OPERATION": REQUEST.operation,
    "DEFAULTS": {
      "LOAD": {
         "transactionTypeId": "Material Load"
      },
      "UNLOAD": {
         "transactionTypeId": "Material UnLoad"
      }
    }
  }
}

data.query:
query($where:InventoryWhereInput!){
  inventory(where:$where){
    edges{
      node{
        id
        productStrategyProcessId
        quantity {
          value unitId
        }
        inventoryStatus{
          id
          defective
          productionLoaded
          productionPrevent
          containment
          active
        }
        locationId
        number
        trackingNumber
        supplierId
        active
        productStrategyProcess {
          id
          unitWeight
          productStrategy {
            id
            product {
              id

            }
          }
        }
      }
    }
  }
}

query productionSetupMaterial($inventoryId : String!){
  data: productionSetupMaterial(where: {inventoryId: {_eq: $inventoryId}}) {
    edges {
      node {
        id
        inventoryId
      }
    }
  }
}

